final class FollowupReviewClient {
 static Object field(Object owner,Class<?> type,String name)throws Exception{var f=type.getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 static void tick(int scene,int age)throws Exception{var mc=Minecraft.getInstance();if(scene>=92)MechanicsReviewClient.tick(scene,age);if(scene>=123)TaintVisualReviewClient.tick(scene,age);
  if(scene==116&&age==25){boolean[] called={false};var before=mc.screen;net.minecraft.client.gui.screens.worldselection.WorldOpenFlows.confirmWorldCreation(mc,null,com.mojang.serialization.Lifecycle.experimental(),()->called[0]=true,false);PhotoLiveClient.check(called[0]&&mc.screen==before,"actual world creation bypasses experimental settings dialog");called[0]=false;net.minecraft.client.gui.screens.worldselection.WorldOpenFlows.confirmWorldCreation(mc,null,com.mojang.serialization.Lifecycle.deprecated(42),()->called[0]=true,false);PhotoLiveClient.check(!called[0]&&mc.screen instanceof net.minecraft.client.gui.screens.ConfirmScreen,"deprecated settings confirmation remains intact");mc.setScreen(null);}
  if(scene>=120&&scene<=122&&age==290){var data=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(BiomeGenerationVerification.root().resolve("result.json"))).getAsJsonObject().getAsJsonArray(scene==120?"forest":"taint");if(scene>=121)data=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(PhotoLiveClient.root().resolve("taint-view-anchor.json"))).getAsJsonArray();var at=new net.minecraft.core.BlockPos(data.get(0).getAsInt(),data.get(1).getAsInt(),data.get(2).getAsInt());PhotoLiveClient.check(mc.level.getChunkSource().hasChunk(at.getX()>>4,at.getZ()>>4),"native client receives complete fresh biome terrain, scene="+scene);PhotoLiveClient.check(mc.level.getBiome(at).is(scene==120?thaumcraft.world.WorldBiomes.MAGICAL:thaumcraft.world.WorldBiomes.TAINT),"native client views actual generated biome, scene="+scene);}
  if(age==20&&scene>=71&&scene<=74)PhotoLiveClient.check(AuraNodeRenderer.revealed()==(scene!=71),"actual node reveal equipment state, scene="+scene);
  if((scene==75||scene==76)&&age==25){var stack=mc.player.getMainHandItem();PhotoLiveClient.check(stack.is(thaumcraft.registry.R2Content.AURA_NODE.get().asItem())&&mc.getItemRenderer().getModel(stack,mc.level,mc.player,0).isCustomRenderer(),"picked aura node uses its animated saved-data item renderer");if(scene==76)mc.setScreen(new net.minecraft.client.gui.screens.inventory.InventoryScreen(mc.player));}
  if(scene>=78&&scene<=82&&age==15){PhotoLiveClient.check(mc.screen instanceof ThaumonomiconScreen,"server opens actual Thaumonomicon, scene="+scene);var mode=scene==78?ThaumcraftClientConfig.BookWindowMode.ORIGINAL:scene==79?ThaumcraftClientConfig.BookWindowMode.SQUARE:ThaumcraftClientConfig.BookWindowMode.FULL;ThaumcraftClientConfig.BOOK_WINDOW_MODE.set(mode);ThaumcraftClientConfig.BOOK_ZOOM.set(1d);mc.screen.resize(mc,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());}
  if(scene>=78&&scene<=81&&age==25){var screen=mc.screen;int w=(Integer)field(screen,net.minecraft.client.gui.screens.inventory.AbstractContainerScreen.class,"imageWidth"),h=(Integer)field(screen,net.minecraft.client.gui.screens.inventory.AbstractContainerScreen.class,"imageHeight");PhotoLiveClient.check(scene==78?w==256&&h==230:scene==79?w==h&&w>256:w>h&&w>256,"actual book viewport respects selected size mode, scene="+scene);}
  if(scene==81&&age==30){var s=mc.screen;PhotoLiveClient.check(s.mouseScrolled(s.width/2d,s.height/2d,0,2)&&ThaumcraftClientConfig.BOOK_ZOOM.get()>1,"native mouse wheel zooms the research tree");double before=(Double)field(s,ThaumonomiconScreen.class,"panX");s.mouseDragged(s.width/2d,s.height/2d,0,20,10);PhotoLiveClient.check((Double)field(s,ThaumonomiconScreen.class,"panX")!=before,"native zoomed tree still pans with mouse drag");}
  if(scene==82&&age==30){PhotoLiveClient.click(mc.getWindow().getGuiScaledWidth()-16,16);PhotoLiveClient.check(mc.screen instanceof net.neoforged.neoforge.client.gui.ConfigurationScreen,"top-right book gear opens real mod settings");}
  if(scene==82&&age==65){mc.screen.onClose();PhotoLiveClient.check(mc.screen instanceof ThaumonomiconScreen,"settings return to the same open book");ThaumcraftClientConfig.BOOK_WINDOW_MODE.set(ThaumcraftClientConfig.BookWindowMode.ORIGINAL);ThaumcraftClientConfig.BOOK_ZOOM.set(1d);}
  if(scene==83&&age==55){var messages=(java.util.List<?>)field(mc.gui.getChat(),net.minecraft.client.gui.components.ChatComponent.class,"allMessages");String expected=net.minecraft.client.resources.language.I18n.get("warp.text.2");boolean found=false;for(var m:messages){var msg=(net.minecraft.client.GuiMessage)m;if(msg.content().getString().equals(expected)){var style=msg.content().getStyle();found=style.isItalic()&&style.getColor()!=null&&style.getColor().getValue()==0xaa00aa;}}PhotoLiveClient.check(found,"actual warp effect appears in chat in original purple italic style");mc.setScreen(new ChatScreen(""));}
  if((scene==84||scene==85||scene==86)&&age==25){var golems=mc.level.getEntitiesOfClass(thaumcraft.entities.ThaumicGolem.class,new net.minecraft.world.phys.AABB(PhotoLiveScene.O).inflate(12));PhotoLiveClient.check(golems.size()==1&&golems.getFirst().hasCustomName()&&golems.getFirst().core()==11,"named fishing golem keeps synced core and actual name tag");}
  if(scene==87&&age==20){mc.setScreen(new FocusRadialScreen(net.minecraft.world.InteractionHand.MAIN_HAND));var entries=(java.util.List<?>)field(mc.screen,FocusRadialScreen.class,"entries");boolean primal=false;for(var e:entries){var getter=e.getClass().getDeclaredMethod("stack");getter.setAccessible(true);var stack=(ItemStack)getter.invoke(e);primal|=stack.is(thaumcraft.registry.R3Equipment.FOCI.get("primal").get());}PhotoLiveClient.check(!primal&&entries.size()==2,"currently installed Primal focus is excluded despite dynamic vis quotes");}
  if((scene==88||scene==89)&&age==60){var far=new net.minecraft.core.BlockPos(0,66,-72);PhotoLiveClient.check(mc.level.getBlockEntity(far) instanceof thaumcraft.blocks.AuraNodeBlockEntity,"sinister node is received beyond its render distance");PhotoLiveClient.check(mc.player.distanceToSqr(far.getCenter())>64*64,"lodestone target is outside the node renderer range");var property=net.minecraft.client.renderer.item.ItemProperties.getProperty(mc.player.getMainHandItem(),net.minecraft.resources.ResourceLocation.parse("thaumcraft:sinister_active"));PhotoLiveClient.check(property.call(mc.player.getMainHandItem(),mc.level,mc.player,0)==(scene==88?1:0),"actual lodestone model predicate responds to unrendered node and facing, scene="+scene);}
  if(scene==91&&age==25)mc.setScreen(new ChatScreen(""));
  if(scene==91&&age==35){var messages=(java.util.List<?>)field(mc.gui.getChat(),net.minecraft.client.gui.components.ChatComponent.class,"allMessages");net.minecraft.network.chat.Style style=null;for(var value:messages){var message=((net.minecraft.client.GuiMessage)value).content();for(var child:message.getSiblings())if(child.getStyle().getClickEvent()!=null)style=child.getStyle();if(style!=null)break;}PhotoLiveClient.check(style!=null&&mc.screen.handleComponentClicked(style),"native chat handles the locate coordinate click");var input=mc.screen.children().stream().filter(w->w instanceof net.minecraft.client.gui.components.EditBox).map(w->(net.minecraft.client.gui.components.EditBox)w).findFirst().orElseThrow();PhotoLiveClient.check(input.getValue().startsWith("/tp @s "),"clicking locate coordinates inserts teleport command into the real chat input");}
 }
 private FollowupReviewClient(){}
}
